{"path": "check.mjs", "content": "import assert from 'node:assert/strict';
import { mergeConfig } from './config.mjs';

// public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }),
  { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }),
  { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }),
  { enabled: false, retries: 0 });

// TypeError cases
for (const bad of [null, undefined, [], 1, 'x', true]) {
  assert.throws(() => mergeConfig(bad, {}), TypeError);
  assert.throws(() => mergeConfig({}, bad), TypeError);
}
assert.throws(() => mergeConfig(), TypeError);

// default overrides = {}
assert.deepEqual(mergeConfig({ a: 1 }), { a: 1 });

// inherited keys ignored
const proto = { inherited: 'nope' };
const withProto = Object.create(proto);
withProto.own = 1;
assert.deepEqual(mergeConfig(withProto, {}), { own: 1 });

// __proto__ and constructor as ordinary data keys from JSON.parse
const d = JSON.parse('{"__proto__": {"x": 1}, "constructor": 5}');
const o = JSON.parse('{"__proto__": {"y": 2}}');
const r = mergeConfig(d, o);
assert.deepEqual(Object.keys(r).sort(), ['__proto__', 'constructor']);
assert.equal(Object.getPrototypeOf(r), Object.prototype);
assert.deepEqual(r['__proto__'], { x: 1, y: 2 });
assert.equal(r.constructor, 5);
// result must not have polluted prototype
assert.equal({}.x, undefined);

// nested merge preserves defaults, override wins
assert.deepEqual(mergeConfig({ n: { a: 1, b: 2 } }, { n: { b: 3, c: 4 } }),
  { n: { a: 1, b: 3, c: 4 } });

// replace when types differ
assert.deepEqual(mergeConfig({ n: { a: 1 } }, { n: 5 }), { n: 5 });
assert.deepEqual(mergeConfig({ n: 5 }, { n: { a: 1 } }), { n: { a: 1 } });

// false/0/null overrides
assert.deepEqual(mergeConfig({ a: 1, b: 2, c: 3 }, { a: false, b: 0, c: null }),
  { a: false, b: 0, c: null });

// no mutation / no retained references
const defaults = { n: { a: 1 }, top: 1 };
const overrides = { n: { b: 2 } };
const out = mergeConfig(defaults, overrides);
assert.deepEqual(defaults, { n: { a: 1 }, top: 1 });
assert.deepEqual(overrides, { n: { b: 2 } });
assert.notEqual(out.n, defaults.n);
assert.notEqual(out.n, overrides.n);
out.n.a = 999;
assert.equal(defaults.n.a, 1);

// independence across repeated calls
const d2 = { n: { a: 1 } };
const r1 = mergeConfig(d2, { n: { b: 2 } });
const r2 = mergeConfig(d2, { n: { c: 3 } });
assert.deepEqual(r1, { n: { a: 1, b: 2 } });
assert.deepEqual(r2, { n: { a: 1, c: 3 } });
assert.notEqual(r1.n, r2.n);

// fresh top-level object
assert.notEqual(mergeConfig({}, {}), mergeConfig({}, {}));

console.log('all checks passed');
"}

